// Issue #15: the JS params pre-check must compute EXACTLY what the deployed v3 contract computes.
// The vectors are generated by the contract's own code (contracts/sealed-bounty/src/escrow_tests.rs
// `canonical_number_vectors`, regenerate with UPDATE_VECTORS=1 cargo test canonical_number_vectors)
// for exotic number tokens (0.0, -0, 1.50, 1e2, 1E+2, u64/i64 limits, 1e400, ...).
// Run: pnpm test (node --test).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import * as judge from '../judge.mjs';

const dir = new URL('../../contracts/sealed-bounty/tests/fixtures/', import.meta.url);
const V = JSON.parse(readFileSync(new URL('canonical-vectors.json', dir), 'utf8'));
const base = JSON.parse(readFileSync(new URL(V.base_fixture, dir), 'utf8')).request_body;
const bodyOf = (v) => {
  assert.ok(base.includes(v.find), `${v.find} in base`);
  return base.replace(v.find, v.replace);
};
const tokenOf = (v) => v.replace.slice(v.find.indexOf(':') + 1);

test('vector file sanity: honest base matches its program, params_hash pinned to the demo hex', () => {
  assert.equal(V.program.params_hash, '61b52e7b87e42a2bc4b6f417d21ba0e9d44f3e1f4ff49fa9d2f3334e5aa0eda7');
  assert.equal(judge.paramsHash(), V.program.params_hash);
  assert.deepEqual(judge.checkRequestAgainstProgram(base, V.program, V.hunter), { ok: true, reason: null });
  assert.ok(V.vectors.length >= 40);
});

for (const v of V.vectors) {
  test(`contract == JS: ${v.name}`, () => {
    const body = bodyOf(v);
    // 1. dispute verdict (what the inbox pre-check promises the owner)
    const got = judge.checkRequestAgainstProgram(body, V.program, V.hunter);
    assert.deepEqual(got, { ok: v.tamper_reason === null, reason: v.tamper_reason }, 'tamper_reason');
    // 2. the contract's request_params_hash (null = rejected by the strict parse)
    assert.equal(judge.requestParamsHash(body), v.params_hash, 'params_hash');
    // 3. the canonical form of the number token on its own
    let canon = null;
    try { canon = judge.canonicalJson(judge.parseJsonLossless(tokenOf(v))); } catch (e) {
      if (!(e instanceof RangeError)) throw e;
    }
    assert.equal(canon, v.canonical_token, 'canonical_token');
  });
}
